// OK: the int widens to double
let d = 1.0 + 1

// compile time error: a decimal never widens
// (decimal vs int)
let e = 1.0m + 1

// OK with explicit cast
let e = 1.0m + cast decimal(1)

// OK: "hello" is a string, and string derives
// from object
let o: object = "hello"
